for row in reader:
    combo = (row['Type1'], row['Type2'])
    if combo not in combos:
        combos[combo] = []
    combos[combo].append(row)

for combo, rows in combos.items():
    with open(f'/app/chunks/{combo[0]}_{combo[1]}.csv', 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['Type1', 'Type2', 'Text', 'ID'])
        for r in rows:
